// src/components/Questionnaire.jsx
import React, { useState } from 'react';
import { getRecommendation } from '../api/appClient';

const Questionnaire = ({ onRecommendationReceived }) => {
    // Örnek olarak kullanıcının sevdiği iki film ID'sini statik olarak veriyoruz
    // (İleride SearchBar'dan seçilen filmler buraya gelecek)
    const [selectedMovies, setSelectedMovies] = useState([238, 597]);
    const [mood, setMood] = useState('Heyecanlı');
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');

    const handleSubmit = async (e) => {
        e.preventDefault();
        setLoading(true);
        setError('');

        const userProfile = {
            currentMood: mood,
            availableTimeMinutes: 120, // Şimdilik sabit
            socialContext: 'Arkadaşlarla' // Şimdilik sabit
        };

        try {
            // appClient üzerinden C# API'mizi tetikliyoruz
            const result = await getRecommendation(selectedMovies, userProfile);

            // Sonucu ana sayfaya (veya ilgili componenti) iletiyoruz
            onRecommendationReceived(result);
        } catch (err) {
            setError('Film önerisi alınamadı. Lütfen bağlantıları kontrol edin.');
        } finally {
            setLoading(false);
        }
    };

    return (
        <div style={{ border: '1px solid #ccc', padding: '20px', borderRadius: '8px' }}>
            <h3>Ruh Halini Seç</h3>
            <form onSubmit={handleSubmit}>
                <select
                    value={mood}
                    onChange={(e) => setMood(e.target.value)}
                    style={{ padding: '8px', marginBottom: '15px', width: '100%' }}
                >
                    <option value="Heyecanlı">Heyecanlı / Aksiyon Bekleyen</option>
                    <option value="Düşünceli">Düşünceli / Felsefi</option>
                    <option value="Eğlenceli">Eğlenceli / Neşeli</option>
                </select>

                <button
                    type="submit"
                    disabled={loading}
                    style={{ padding: '10px 20px', cursor: loading ? 'not-allowed' : 'pointer' }}
                >
                    {loading ? 'Yapay Zeka Düşünüyor...' : 'Bana Film Öner'}
                </button>
            </form>
            {error && <p style={{ color: 'red' }}>{error}</p>}
        </div>
    );
};

export default Questionnaire;
